observe.script:
(() => {
  const st = window.__bhxDino || (window.__bhxDino = {t0: performance.now(), lastHash: -1, lastChange: performance.now(), prevNear: null, prevT: 0, speed: 0});
  const now = performance.now();
  const c = document.querySelector('canvas.runner-canvas');
  if (!c) return {ready:false, stalled:true, elapsed_ms: now-st.t0, gap:null, trigger:70, airborne:false, speed:0};
  const W=c.width, H=c.height;
  const d=c.getContext('2d').getImageData(0,0,W,H).data;
  const dark=(x,y)=>{const i=(y*W+x)*4;return d[i]<110&&d[i+1]<110&&d[i+2]<110&&d[i+3]>100;};
  let h=0; for(let i=0;i<d.length;i+=137) h=(h*31+d[i])>>>0;
  if (h !== st.lastHash) { st.lastHash=h; st.lastChange=now; }
  let ground=-1, best=0;
  for (let y=Math.floor(H*0.6); y<H; y++) {
    let n=0; for (let x=0;x<W;x+=2) if (dark(x,y)) n++;
    if (n>best) { best=n; ground=y; }
  }
  let dbot=0;
  for (let y=0; y<ground-1; y++) for (let x=0; x<45; x++) if (dark(x,y) && y>dbot) dbot=y;
  const bandTop = Math.max(0, Math.floor(ground*0.3));
  const isObs = (x) => {
    let n=0, top=H;
    for (let y=bandTop; y<ground-6; y++) if (dark(x,y)) { n++; if (y<top) top=y; }
    return (n>=3 && top<=ground-8) ? top : -1;
  };
  let nearest=null, nw=0, last=-999;
  for (let x=70; x<W; x++) {
    const top = isObs(x);
    if (top >= 0) { if (nearest===null) nearest=x; last=x; nw=x-nearest+1; }
    else if (nearest!==null && x-last > 3) break;
  }
  if (nw < 6) { nearest=null; nw=0; }
  const airborne = dbot < ground-4;
  if (nearest!==null && st.prevNear!==null && now-st.prevT>0) {
    const dx = st.prevNear - nearest;
    if (dx > 0 && dx < 120) st.speed = dx/(now-st.prevT)*1000;
  }
  st.prevNear = nearest; st.prevT = now;
  const trigger = Math.max(45, (st.speed || 350) * 0.22 - 8);
  return {ready:true, gap: nearest===null?null:nearest-42, nw,
          airborne, stalled: now-st.lastChange>400,
          elapsed_ms: now-st.t0, speed: Math.round(st.speed), trigger};
})()
